from pathlib import Path
prog='''def transform(grid):
    # The figure is partitioned into complete 2x2 squares and L triominoes.
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    pieces = []
    for r in range(h-1):
        for c in range(w-1):
            sq = {(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
            if sq <= cells:
                pieces.append((sq, 1))
            shapes = [
                ({(r,c+1),(r+1,c),(r+1,c+1)}, 2), # missing top-left
                ({(r,c),(r,c+1),(r+1,c)}, 3),     # missing bottom-right? corrected below
                ({(r,c),(r+1,c),(r+1,c+1)}, 3),   # missing top-right? corrected below
                ({(r,c),(r,c+1),(r+1,c+1)}, 4),
            ]
            # Mapping from demos: 2 = 01/11; 3 = 11/01; 4 = 10/11.
            shapes = [
                ({(r,c+1),(r+1,c),(r+1,c+1)}, 2),
                ({(r,c),(r,c+1),(r+1,c)}, 0),
                ({(r,c),(r+1,c),(r+1,c+1)}, 3),
                ({(r,c),(r,c+1),(r+1,c+1)}, 4),
            ]
            for shape, color in shapes:
                if color and shape <= cells:
                    pieces.append((shape, color))
    by_cell = {cell: [] for cell in cells}
    for p in pieces:
        for cell in p[0]:
            by_cell[cell].append(p)
    # Favor square blocks, then deterministic L choices.
    for cell in by_cell:
        by_cell[cell].sort(key=lambda p: (-len(p[0]), p[1], sorted(p[0])))
    def solve(remaining):
        if not remaining:
            return []
        cell = min(remaining)
        for shape, color in by_cell[cell]:
            if shape <= remaining:
                rest = solve(remaining - shape)
                if rest is not None:
                    return [(shape,color)] + rest
        return None
    tiling = solve(cells)
    if tiling is None:
        raise ValueError('No tiling into square/L pieces')
    out = [[0 for _ in range(w)] for _ in range(h)]
    for shape,color in tiling:
        for r,c in shape:
            out[r][c] = color
    return out
'''
